{"query":"
  query GetAaveAppConfig {
    aaveConfig(id: 1) {
      id
      adapterAddress
      vaultBtcAddress
      btcVaultRegistryAddress
      vaultBtcReserveId
    }
    aaveReserves {
      items {
        id
        underlying
        hub
        assetId
        decimals
        dynamicConfigKey
        paused
        frozen
        borrowable
        collateralRisk
        collateralFactor
        underlyingToken {
          address
          symbol
          name
          decimals
        }
      }
    }
  }
","operationName":"GetAaveAppConfig"}

{"query":"
  query GetUniversalChallengers {
    universalChallengerVersions {
      items {
        version
        challengerInfo {
          id
          btcPubKey
        }
      }
    }
  }
","operationName":"GetUniversalChallengers"}

{"query":"
  query GetApplications {
    applications {
      items {
        id
        name
        registeredAt
        blockNumber
        transactionHash
      }
    }
  }
","operationName":"GetApplications"}

{"query":"
  query GetAppProviders($appController: String!) {
    vaultProviders(where: { applicationEntryPoint: $appController }) {
      items {
        id
        btcPubKey
        name
        rpcUrl
        metadataStatus
        metadataRejectionReason
      }
    }
    vaultKeeperApplications(where: { applicationEntryPoint: $appController }) {
      items {
        vaultKeeper
        version
        vaultKeeperInfo {
          btcPubKey
        }
      }
    }
  }
","variables":{"appController":"0x31bc43cab2d91b3016bee8e9fc1194d46d7b0590"},"operationName":"GetAppProviders"}

{"query":"
  query GetVaultsByProvider($vaultProvider: String!) {
    vaults(where: { vaultProvider: $vaultProvider }) {
      items {
        amount
        status
        activatedAt
      }
      totalCount
    }
  }
","variables":{"vaultProvider":"0xaf8d9d665f4e27f3966a074dce5c50684bfbe358"},"operationName":"GetVaultsByProvider"}

{"query":"
  query GetAaveActivePositionsWithCollaterals($depositorAddress: String!) {
    aavePositions(where: { depositorAddress: $depositorAddress }) {
      items {
        depositorAddress
        proxyContract
        totalCollateral
        createdAt
        updatedAt
        collaterals {
          items {
            depositorAddress
            vaultId
            amount
            addedAt
            removedAt
            liquidationIndex
            vault {
              id
              peginTxHash
              amount
              status
              vaultProvider
              inUse
              depositorBtcPubKey
              depositorPayoutBtcAddress
              unsignedPrePeginTx
              offchainParamsVersion
            }
          }
        }
      }
    }
  }
","variables":{"depositorAddress":"0x67158c9891fb47e0ca719263392f4657b1c75002"},"operationName":"GetAaveActivePositionsWithCollaterals"}

{"query":"
  query GetAavePriceCandles(
    $feed: String!
    $interval: aavePriceInterval!
    $limit: Int!
  ) {
    aavePriceCandles(
      where: { feed: $feed, interval: $interval }
      orderBy: "bucketStart"
      orderDirection: "desc"
      limit: $limit
    ) {
      items {
        bucketStart
        open
        high
        low
        close
        decimals
      }
    }
  }
","variables":{"feed":"0xa5c0105b71d9d2cadc151a1875a5b71c85abf8db","interval":"day_1","limit":180},"operationName":"GetAavePriceCandles"}
